import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    pts = [(0, 0)] * n
    for i in range(n):
        pts[i] = (data[1 + 2*i], data[2 + 2*i])

    # A state is represented by a bitset.  Applying a move keeps the
    # pivot and all points incomparable with it.
    allmask = (1 << n) - 1
    keep = []
    for k, (xk, yk) in enumerate(pts):
        m = 0
        for i, (x, y) in enumerate(pts):
            if i == k or (x < xk and y > yk) or (x > xk and y < yk):
                m |= 1 << i
        keep.append(m)

    seen = {allmask}
    stack = [allmask]
    while stack:
        s = stack.pop()
        t = s
        while t:
            b = t & -t
            k = b.bit_length() - 1
            t -= b
            ns = s & keep[k]
            if ns not in seen:
                seen.add(ns)
                stack.append(ns)
    print(len(seen) % 998244353)

if __name__ == '__main__':
    main()

