import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    groups = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        l, r, x = data[p] - 1, data[p + 1] - 1, data[p + 2] - 1
        p += 3
        groups[x].append((l, r))

    # mins[k][l] is the smallest right endpoint of a condition centered
    # at k whose left endpoint is at least l.
    mins = [[n] * n for _ in range(n)]
    for k in range(n):
        at_left = [n] * n
        for a, b in groups[k]:
            if b < at_left[a]:
                at_left[a] = b
        best = n
        row = mins[k]
        for l in range(n - 1, -1, -1):
            if at_left[l] < best:
                best = at_left[l]
            row[l] = best

    fact = [1] * (n + 1)
    invfact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    # Choose table: choose[a][b] = C(a,b).
    choose = [[0] * (n + 1) for _ in range(n + 1)]
    for a in range(n + 1):
        choose[a][0] = choose[a][a] = 1
        for b in range(1, a):
            choose[a][b] = (choose[a - 1][b - 1] + choose[a - 1][b]) % MOD

    dp = [[0] * n for _ in range(n)]
    for length in range(1, n + 1):
        choose_row = choose[length - 1]
        for l in range(n - length + 1):
            r = l + length - 1
            total = 0
            for k in range(l, r + 1):
                if mins[k][l] <= r:
                    continue
                left = dp[l][k - 1] if k > l else 1
                right = dp[k + 1][r] if k < r else 1
                total = (total + left * right * choose_row[k - l]) % MOD
            dp[l][r] = total
    print(dp[0][n - 1])

if __name__ == '__main__':
    main()

