import sys
from collections import defaultdict

def solve(N, A):
    spf = list(range(1001))
    for i in range(2, 32):
        if spf[i] == i:
            for j in range(i * i, 1001, i):
                if spf[j] == j:
                    spf[j] = i

    edges = defaultdict(dict)
    for idx, a in enumerate(A, 1):
        x = a
        while x > 1:
            p = spf[x]
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            edges[p][idx] = e

    answer = 1
    for p, edge_exp in edges.items():
        # dp[y]: sum of p^(sum of normalized heights so far) over choices,
        # where the current normalized height is y.
        dp = {0: 1}
        previous_edge = 0
        power_cache = {0: 1}

        def power(exponent):
            if exponent not in power_cache:
                power_cache[exponent] = pow(p, exponent, MOD)
            return power_cache[exponent]

        for i, e in edge_exp.items():
            # Vertices between the previous nonzero edge and this edge
            # have unchanged normalized height.
            gap = i - previous_edge - 1
            if gap:
                dp = {y: value * power(gap * y) % MOD
                      for y, value in dp.items()}

            nxt = defaultdict(int)
            for y, value in dp.items():
                for step in (-e, e):
                    new_y = y + step
                    shift = 0
                    if new_y < 0:
                        shift = -new_y
                        new_y = 0
                    # All i old heights increase by shift; add the new height.
                    add_exp = i * shift + new_y
                    nxt[new_y] = (nxt[new_y] + value * power(add_exp)) % MOD
            dp = nxt
            previous_edge = i

        # Account for vertices after the last nonzero edge.
        gap = N - previous_edge - 1
        if gap:
            dp = {y: value * power(gap * y) % MOD
                  for y, value in dp.items()}
        answer = answer * (sum(dp.values()) % MOD) % MOD

    print(answer)

