import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:]
    limit = max(values)

    # Smallest prime factor for every number up to limit.
    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, limit + 1, p):
                if spf[x] == x:
                    spf[x] = p

    # Omega[x] is the number of prime factors of x, counted with multiplicity.
    omega = [0] * (limit + 1)
    for x in range(2, limit + 1):
        omega[x] = omega[x // spf[x]] + 1

    xor_sum = 0
    for x in values:
        xor_sum ^= omega[x]
    print("Anna" if xor_sum else "Bruno")

if __name__ == "__main__":
    main()

