class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, idx))

        largest = second = 0
        owner = -1
        base = 0
        gains = [0] * len(conflictingPairs)

        for right in range(1, n + 1):
            for left, idx in ending[right]:
                if left > largest:
                    second, largest, owner = largest, left, idx
                elif left == largest:
                    second = largest
                elif left > second:
                    second = left

            # Starts must be strictly greater than the largest conflicting
            # left endpoint among pairs whose right endpoint is <= right.
            base += right - largest
            if largest > second:
                gains[owner] += largest - second

        return base + max(gains)

