import sys
from math import gcd

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[:2]
    machines = [tuple(data[i:i + 4]) for i in range(2, len(data), 4)]

    def feasible(target):
        total_cost = 0
        for a, p, b, q in machines:
            period = b // gcd(a, b)
            xmax = (target + a - 1) // a
            best = 10**30

            # For a fixed x modulo period, the cost is linear between
            # successive breakpoints, so its minimum is at an endpoint.
            for r in range(min(period, xmax + 1)):
                candidates = {r}
                for bound in (xmax - 1, xmax):
                    if bound >= r:
                        candidates.add(r + (bound - r) // period * period)
                for x in candidates:
                    remaining = max(0, target - a * x)
                    y = (remaining + b - 1) // b
                    best = min(best, x * p + y * q)

            total_cost += best
            if total_cost > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

