class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 1_000_000_007
        n = len(s)

        # Pascal's triangle, modulo mod.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % mod

        # If x has m set bits, one operation maps it to m. Thus x is
        # k-reducible exactly when m reaches 1 in at most k-1 more steps.
        good = [False] * (n + 1)
        for m in range(1, n + 1):
            value = m
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            good[m] = steps <= k - 1

        # At each 1 in s, count numbers that first differ there by using 0;
        # the remaining suffix can then be chosen freely with the required
        # number of set bits.
        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for m in range(1, n + 1):
                    if good[m]:
                        need = m - prefix_ones
                        if 0 <= need <= remaining:
                            answer += comb[remaining][need]
                prefix_ones += 1

        return answer % mod

