import sys
from collections import deque

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    people = [(next(it)-1, next(it)-1) for _ in range(m)]
    queries = [(next(it)-1, next(it)-1) for _ in range(q)]
    out = []
    for left, right in queries:
        parent = list(range(n))
        size = [1] * n
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        for i in range(left, right + 1):
            a, b = people[i]
            a, b = find(a), find(b)
            if a != b:
                if size[a] < size[b]:
                    a, b = b, a
                parent[b] = a
                size[a] += size[b]
        # Strict inequalities on the quotient graph.
        edges = [set() for _ in range(n)]
        indeg = [0] * n
        for i in range(left, right + 1):
            s, t = people[i]
            a = find(s)
            if s < t:
                for x in range(s + 1, t):
                    b = find(x)
                    if a != b and b not in edges[a]:
                        edges[a].add(b)
                        indeg[b] += 1
            else:
                for x in range(t + 1, s):
                    b = find(x)
                    if a != b and a not in edges[b]:
                        edges[b].add(a)
                        indeg[a] += 1
        dq = deque(i for i in range(n) if find(i) == i and indeg[i] == 0)
        seen = 0
        while dq:
            v = dq.popleft()
            seen += 1
            for w in edges[v]:
                indeg[w] -= 1
                if indeg[w] == 0:
                    dq.append(w)
        out.append('Yes' if seen == sum(1 for i in range(n) if find(i) == i) else 'No')
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    solve()

