import sys
from collections import deque

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    graph = [row.decode() for row in data[1:1 + n]]

    # pred[v][c] are vertices with a c-labeled edge into v;
    # succ[v][c] are vertices reached from v by a c-labeled edge.
    pred = [[[] for _ in range(26)] for _ in range(n)]
    succ = [[[] for _ in range(26)] for _ in range(n)]
    dist = [[-1] * n for _ in range(n)]
    queue = deque()

    # Empty paths and single-edge paths are the center of every palindrome.
    for i in range(n):
        dist[i][i] = 0
        queue.append((i, i))
    for i in range(n):
        for j, ch in enumerate(graph[i]):
            if ch != '-':
                c = ord(ch) - ord('a')
                succ[i][c].append(j)
                pred[j][c].append(i)
                if dist[i][j] == -1:
                    dist[i][j] = 1
                    queue.append((i, j))

    # Expand a palindrome from its two ends with equal-labeled edges.
    while queue:
        x, y = queue.popleft()
        new_dist = dist[x][y] + 2
        for c in range(26):
            for a in pred[x][c]:
                row = dist[a]
                for b in succ[y][c]:
                    if row[b] == -1:
                        row[b] = new_dist
                        queue.append((a, b))

    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in dist))

if __name__ == '__main__':
    solve()

