class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        rem = list(range(1, n + 1))
        ans = []
        prev = None
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i
        while rem:
            m = len(rem)
            chosen = None
            for x in rem:
                q = x & 1
                if prev is not None and q == prev:
                    continue
                o = sum(y & 1 for y in rem if y != x)
                e = m - 1 - o
                length = m - 1
                start = 1 - q
                exp_o = (length + (1 if start == 1 else 0)) // 2
                if o != exp_o:
                    cnt = 0
                else:
                    cnt = fact[o] * fact[e]
                if k > cnt:
                    k -= cnt
                else:
                    chosen = x
                    break
            if chosen is None:
                return []
            ans.append(chosen)
            rem.remove(chosen)
            prev = chosen & 1
        return ans

