class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = []
        for i in range(m):
            if i == n - 1 - i:
                coeff.append(pow(10, i, k))
            else:
                coeff.append((pow(10, i, k) + pow(10, n - 1 - i, k)) % k)

        # can[i][r] is true if positions i..m-1 can contribute residue r.
        can = [bytearray(k) for _ in range(m + 1)]
        can[m][0] = 1
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            nxt = can[i + 1]
            cur = can[i]
            for r in range(k):
                if nxt[r]:
                    for d in range(10):
                        cur[(r + d * c) % k] = 1

        # Choose each digit greedily, retaining only choices completable to residue 0.
        remaining = 0
        half = []
        for i, c in enumerate(coeff):
            lowest = 1 if i == 0 else 0
            for d in range(9, lowest - 1, -1):
                needed = (remaining - d * c) % k
                if can[i + 1][needed]:
                    half.append(str(d))
                    remaining = needed
                    break

        h = ''.join(half)
        return h + (h[:-1][::-1] if n % 2 else h[::-1])

