    n = data[0]
    adj = [[] for _ in range(n)]
    p = 1
    for _ in range(n - 1):
        u, v, w = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        adj[u].append((v, w))
        adj[v].append((u, w))

    parent = [-1] * n
    parent[0] = 0
    edge_len = [0] * n
    order = [0]
    for v in order:
        for x, w in adj[v]:
            if x != parent[v]:
                parent[x] = v
                edge_len[x] = w
                order.append(x)

    heaps = [None] * n
    for v in reversed(order):
        children = [x for x, _ in adj[v] if parent[x] == v]
        for x in children:
            h = heaps[x]
            heapq.heapreplace(h, h[0] - edge_len[x])

        if children:
            base = max(children, key=lambda x: len(heaps[x]))
            h = heaps[base]
            for x in children:
                if x != base:
                    other = heaps[x]
                    for value in other:
