            for x in children:
                heaps[x] = None
        else:
            h = []
        heapq.heappush(h, 0)
        heaps[v] = h

    values = sorted(-x for x in heaps[0], reverse=True)
    total = 0
    out = []
    for value in values:
        total += value
        out.append(str(2 * total))
