import sys

MOD = 998244353

def solve_case(grid):
    H = len(grid)
    W = len(grid[0])
    # Use the shorter dimension for the enumerated vertical-edge boundary state.
    if W > H:
        grid = [''.join(grid[i][j] for i in range(H)) for j in range(W)]
        H, W = W, H

    # For a tile, let v be the top-edge occupation and h the left-edge
    # occupation. The local rules determine bottom/right except for the
    # two possible corner orientations of A.
    answer = 0
    for initial in range(1 << W):
        v = [(initial >> j) & 1 for j in range(W)]
        ways = 1
        for row in grid:
            # Count cyclic horizontal-edge assignments for this row.
            count = 0
            for first in (0, 1):
                left = first
                for j, tile in enumerate(row):
                    right_required = None
                    if tile == 'A':
                        # A turns: its left and right edges differ.
                        right = left ^ 1
                    else:
                        # B is straight; its horizontal edges are both
                        # occupied precisely when its vertical edges are empty.
                        target = 1 - v[j]
                        if left != target:
                            break
                        right = target
                    left = right
                else:
                    if left == first:
                        count += 1
            ways = ways * count % MOD
            if not ways:
                break
            for j, tile in enumerate(row):
                if tile == 'A':
                    v[j] ^= 1
        if any(v):
            continue
        answer = (answer + ways) % MOD
    return answer

def main():
    data = sys.stdin.buffer
    t = int(data.readline())
    out = []
    for _ in range(t):
        h, w = map(int, data.readline().split())
        grid = [data.readline().decode().strip() for _ in range(h)]
        out.append(str(solve_case(grid)))
    print('\n'.join(out))

if __name__ == '__main__':
    main()

