from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first = p.index('*')
        second = p.index('*', first + 1)
        a = p[:first]
        b = p[first + 1:second]
        c = p[second + 1:]
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))

            m = len(t)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = prefix[j - 1]
                if t[i] == t[j]:
                    j += 1
                prefix[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = prefix[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = prefix[j - 1]
            return result

        starts_a = occurrences(a)
        starts_b = occurrences(b)
        starts_c = occurrences(c)
        answer = n + 1

        for start_b in starts_b:
            end_b = start_b + len(b)

            if a:
                # The latest A ending before B gives the shortest left side.
                k = bisect_right(starts_a, start_b - len(a))
                if k == 0:
                    continue
                start = starts_a[k - 1]
            else:
                start = start_b

            if c:
                k = bisect_left(starts_c, end_b)
