from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for node in range(1, n):
            children[parent[node]].append(node)

        # Iterative postorder traversal; child lists are already in increasing order.
        order = []
        stack = [(0, 0)]
        while stack:
            node, visited = stack.pop()
            if visited:
                order.append(node)
            else:
                stack.append((node, 1))
                for child in reversed(children[node]):
                    stack.append((child, 0))

        position = [0] * n
        for i, node in enumerate(order):
            position[node] = i

        # Each subtree occupies a contiguous interval in postorder.
        subtree_size = [1] * n
        for node in order:
            p = parent[node]
            if p != -1:
                subtree_size[p] += subtree_size[node]

        text = ''.join(s[node] for node in order)

        # Manacher radii: odd[i] counts palindrome radii including center i;
        # even[i] counts radii centered immediately before i.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < n and text[i - radius] == text[i + radius]:
                radius += 1
            odd[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - radius - 1 >= 0 and i + radius < n and text[i - radius - 1] == text[i + radius]:
                radius += 1
            even[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius, i + radius - 1

        answer = [False] * n
        for node in range(n):
            end = position[node] + 1
            length = subtree_size[node]
            start = end - length
            if length % 2:
                center = (start + end - 1) // 2
                answer[node] = odd[center] >= length // 2 + 1
            else:
                center = start + length // 2
                answer[node] = even[center] >= length // 2
        return answer

