from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Minimum prefix sum seen at each prefix-index residue modulo k.
        min_prefix = [None] * k
        min_prefix[0] = 0

        prefix = 0
        answer = None
        for i, value in enumerate(nums, 1):
            prefix += value
            residue = i % k

            # Matching residues give a subarray whose length is divisible by k.
            previous = min_prefix[residue]
            if previous is not None:
                candidate = prefix - previous
                if answer is None or candidate > answer:
                    answer = candidate

            if previous is None or prefix < previous:
                min_prefix[residue] = prefix

        return answer

