from heapq import heappush, heappop

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        # Sieve all possible values (the inputs have at most four digits).
        limit = 10000
        is_prime = bytearray(b'\x01') * limit
        is_prime[0:2] = b'\x00\x00'
        for p in range(2, 100):
            if is_prime[p]:
                for x in range(p * p, limit, p):
                    is_prime[x] = 0

        if is_prime[n] or is_prime[m]:
            return -1

        digits = len(str(n))
        lower = 10 ** (digits - 1)
        upper = 10 ** digits - 1
        place_values = [10 ** (digits - 1 - i) for i in range(digits)]

        # The starting value is included in the transformation cost.
        dist = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heappop(heap)
            if cost != dist.get(value):
                continue
            if value == m:
                return cost

            for i, ch in enumerate(str(value)):
                digit = ord(ch) - ord('0')
                place = place_values[i]
                for change in (-1, 1):
                    new_digit = digit + change
                    if not 0 <= new_digit <= 9:
                        continue
                    neighbor = value + change * place
                    # Keep the number at the original digit length.
                    if not lower <= neighbor <= upper or is_prime[neighbor]:
                        continue
                    new_cost = cost + neighbor
                    if new_cost < dist.get(neighbor, float('inf')):
                        dist[neighbor] = new_cost
                        heappush(heap, (new_cost, neighbor))

        return -1

