def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    neg = -10**30
    dp = [neg, neg]  # best sum of a nonempty survivor sequence ending at even/odd index
    for i, x in enumerate(a, 1):
        p = i & 1
        if p == 1:
            dp[p] = max(dp[p], x)  # start with the first survivor (which must be at odd index)
        if dp[1 - p] != neg:
            dp[p] = max(dp[p], dp[1 - p] + x)
    ans = dp[n & 1]
    if n % 2 == 0:
        ans = max(ans, 0)  # empty final stack is feasible for even N
    print(ans)

