class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Reversing the edges lets us find all nodes that can reach 0
        # by traversing outward from 0.
        reverse_graph = [[] for _ in range(n)]
        for a, b, weight in edges:
            reverse_graph[b].append((a, weight))

        weights = sorted({weight for _, _, weight in edges})

        def all_reach_zero(max_weight: int) -> bool:
            seen = bytearray(n)
            seen[0] = 1
            stack = [0]
            while stack:
                node = stack.pop()
                for predecessor, weight in reverse_graph[node]:
                    if weight <= max_weight and not seen[predecessor]:
                        seen[predecessor] = 1
                        stack.append(predecessor)
            return sum(seen) == n

        if not all_reach_zero(weights[-1]):
            return -1

        low, high = 0, len(weights) - 1
        while low < high:
            mid = (low + high) // 2
            if all_reach_zero(weights[mid]):
                high = mid
            else:
                low = mid + 1
        return weights[low]

