class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # A state assigns colors to a symmetric pair (left, right).
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        # Add symmetric pairs moving inward. Both sides must differ from
        # the corresponding colors in the previous pair.
        for i in range(1, n // 2):
            ndp = [float('inf')] * 6
            for j, (left, right) in enumerate(states):
                pair_cost = cost[i][left] + cost[n - 1 - i][right]
                for k, (prev_left, prev_right) in enumerate(states):
                    if left != prev_left and right != prev_right:
                        ndp[j] = min(ndp[j], dp[k] + pair_cost)
            dp = ndp

        return min(dp)

